// Probability: Theory and Examples (Durrett) — Chapter 4, §§4.1–4.2: helpers shared by ch04-a.js, ch04-a1.js, ch04-a2.js.
//
// Pictures that recur: Ω = [0,1) with Lebesgue measure and σ-fields generated by a finite partition into cells (draggable cut
// handles snapped to a grid of 1/48, so nested partitions are exactly nested), conditional expectation as cell averaging on a
// fine grid, step-function drawing, and seeded ±1 walks / multiplicative martingales.

export * from './ch03.shared.js';
import { clampN } from './ch03.shared.js';

// ------------------------------------------------------------------ Ω = [0,1) on a grid
/** Grid size: divisible by 48, so every cut that is a multiple of 1/48 falls on a grid boundary. */
export const GN = 1200;
export const SNAP = 48;
/** Sample a function at the midpoints of the GN grid cells. */
export function gridOf(f, n = GN) { const a = new Float64Array(n); for (let i = 0; i < n; i++) a[i] = f((i + 0.5) / n); return a; }
const ix = (c, n) => Math.round(c * n);
/** Means of a gridded function over the cells delimited by cuts [0, c1, …, 1]. */
export function cellMeans(arr, cuts) {
  const n = arr.length, out = [];
  for (let k = 0; k + 1 < cuts.length; k++) {
    const a = ix(cuts[k], n), b = ix(cuts[k + 1], n); let s = 0;
    for (let i = a; i < b; i++) s += arr[i];
    out.push(b > a ? s / (b - a) : 0);
  }
  return out;
}
/** E(arr | cells) as a gridded function. */
export function project(arr, cuts) {
  const n = arr.length, m = cellMeans(arr, cuts), out = new Float64Array(n);
  for (let k = 0; k + 1 < cuts.length; k++) out.fill(m[k], ix(cuts[k], n), ix(cuts[k + 1], n));
  return out;
}
/** Integral (mean over [0,1)) of a gridded function over [a, b). */
export function intOver(arr, a, b) { const n = arr.length; let s = 0; for (let i = Math.round(a * n); i < Math.round(b * n); i++) s += arr[i]; return s / n; }
export const meanOf = (arr) => { let s = 0; for (let i = 0; i < arr.length; i++) s += arr[i]; return s / arr.length; };
export const normP = (arr, p) => { let s = 0; for (let i = 0; i < arr.length; i++) s += Math.abs(arr[i]) ** p; return (s / arr.length) ** (1 / p); };
export const maxAbsDiff = (a, b) => { let d = 0; for (let i = 0; i < a.length; i++) d = Math.max(d, Math.abs(a[i] - b[i])); return d; };
/** Draw a gridded function as a polyline on the stage. */
export function drawGrid(S, arr, o = {}) { const n = arr.length; S.path(Array.from(arr, (y, i) => [(i + 0.5) / n, y]), o); }
/** Draw a step function (cell values vals over cuts) with optional vertical joins. */
export function drawSteps(S, cuts, vals, o = {}) {
  const pts = [];
  for (let k = 0; k < vals.length; k++) { pts.push([cuts[k], vals[k]], [cuts[k + 1], vals[k]]); if (o.join && k + 1 < vals.length) pts.push(null); }
  S.path(pts, { color: o.color || 'orange', width: o.width ?? 3, alpha: o.alpha, dash: o.dash });
}
/** Shade the area between the step function and a baseline. */
export function fillSteps(S, cuts, vals, o = {}) {
  for (let k = 0; k < vals.length; k++) S.rect(cuts[k], Math.min(0, vals[k]), cuts[k + 1], Math.max(0, vals[k]), { fill: o.color || 'orange', fillAlpha: o.alpha ?? 0.18, stroke: false });
}
/** The cell index (0-based) containing x. */
export const cellOf = (cuts, x) => { for (let k = 0; k + 1 < cuts.length; k++) if (x < cuts[k + 1]) return k; return cuts.length - 2; };
/** Thin vertical lines at the interior cuts. */
export function drawCuts(S, cuts, o = {}) { for (let k = 1; k + 1 < cuts.length; k++) S.vline(cuts[k], { color: o.color || 'faint', width: o.width ?? 1, dash: o.dash ?? [3, 4], alpha: o.alpha }); }
/**
 * A lane of draggable cut handles at height y. Returns { get() → sorted unique cuts [0, …, 1] snapped to 1/48, hs, set(xs) }.
 * Handles are snapped to the grid and kept at least one grid step apart from the ends.
 */
export function cutLane(S, init, y, o = {}) {
  const snap = (x) => clampN(Math.round(x * SNAP) / SNAP, 1 / SNAP, 1 - 1 / SNAP);
  const L = { y };
  L.hs = init.map((x) => S.handle(snap(x), y, { color: o.color || 'orange', r: o.r ?? 7, constrain: (xx) => [snap(xx), L.y], label: o.label }));
  L.get = () => { const xs = [...new Set(L.hs.map((h) => snap(h.x)))].sort((a, b) => a - b); return [0, ...xs, 1]; };
  L.set = (xs) => xs.forEach((x, i) => L.hs[i] && L.hs[i].set(snap(x), L.y));
  /** Move the whole lane to height y (call inside render after changing the stage's view). */
  L.setY = (yy) => { L.y = yy; L.hs.forEach((h) => h.set(h.x, yy)); };
  return L;
}
/** Is every cut of A also a cut of B (σ(A) ⊂ σ(B))? */
export const nestedIn = (A, B) => A.every((a) => B.some((b) => Math.abs(a - b) < 1e-9));
/** Cell weights as fractions of 1. */
export const widths = (cuts) => cuts.slice(1).map((c, k) => c - cuts[k]);

/** A small library of integrable random variables on [0,1). */
export const XF = {
  wave: { label: 'wave', f: (w) => 1.1 * Math.sin(2 * Math.PI * 1.5 * w) + 0.9 * w },
  bump: { label: 'bump', f: (w) => 1.7 * Math.exp(-(((w - 0.3) / 0.11) ** 2)) - 0.9 * Math.exp(-(((w - 0.76) / 0.16) ** 2)) + 0.2 },
  ramp: { label: 'ramp', f: (w) => 2.2 * w * w - 0.7 },
  saw: { label: 'sawtooth', f: (w) => 1.6 * (((w * 3.3) % 1) - 0.5) + 0.3 * Math.cos(2 * Math.PI * w) },
};
export const xfOpts = (keys = Object.keys(XF)) => keys.map((k) => ({ value: k, label: XF[k].label }));
export const Y_RANGE = [-1.9, 2.5];

// ------------------------------------------------------------------ walks and martingales
/** m paths of a ±1 walk with up-probability p, n steps each, from x0 (Float64Array of length n + 1). */
export function walkPaths(r, m, n, p = 0.5, x0 = 0) {
  const out = [];
  for (let k = 0; k < m; k++) { const a = new Float64Array(n + 1); a[0] = x0; for (let i = 1; i <= n; i++) a[i] = a[i - 1] + (r() < p ? 1 : -1); out.push(a); }
  return out;
}
/** Mean over paths at each time. */
export function meanPaths(paths, f = (x) => x) {
  const n = paths[0].length, out = new Float64Array(n);
  for (const a of paths) for (let i = 0; i < n; i++) out[i] += f(a[i]);
  for (let i = 0; i < n; i++) out[i] /= paths.length;
  return out;
}
export const quantileOf = (arr, q) => { const s = Array.from(arr).sort((a, b) => a - b); return s[Math.min(s.length - 1, Math.max(0, Math.floor(q * s.length)))]; };
/** Number of upcrossings of [a, b] by a path up to index n (Durrett's N_{2k-1} = first time ≤ a, N_{2k} = then first time ≥ b). */
export function upcrossings(path, a, b, n = path.length - 1) {
  let U = 0, below = false;
  for (let i = 0; i <= n; i++) { if (!below) { if (path[i] <= a) below = true; } else if (path[i] >= b) { U++; below = false; } }
  return U;
}
/** Exact E φ(x0 + S_n) for S_n a ±1 walk with up-probability p. */
export function expectPhi(phi, n, p = 0.5, x0 = 0) {
  const pm = binomPmf(n, p); let s = 0;
  for (let k = 0; k <= n; k++) s += pm[k] * phi(x0 + 2 * k - n);
  return s;
}
import { binomPmf } from './ch03.shared.js';
